<?php
declare(strict_types=1);

require_once __DIR__ . '/../includes/auth.php'; require_role('owner');
function menu_redirect(string $message): never { $_SESSION['flash']=$message; redirect('/owner/menu.php'); }
if ($_SERVER['REQUEST_METHOD']==='POST') { if(!verify_csrf()){http_response_code(400);exit('Invalid request.');} $a=(string)($_POST['action']??'');$id=(int)($_POST['id']??0); if(in_array($a,['archive','restore','availability'],true)){ $field=$a==='availability'?'is_available':'is_archived';$value=$a==='availability'?(int)!empty($_POST['is_available']):($a==='archive'?1:0);$pdo->prepare("UPDATE menu_items SET $field=:v WHERE id=:id")->execute(['v'=>$value,'id'=>$id]);menu_redirect('Menu item updated.'); } $name=trim((string)($_POST['name']??''));$cat=(int)($_POST['category_id']??0);$price=filter_var($_POST['price']??null,FILTER_VALIDATE_FLOAT);if($name===''||$cat<1||$price===false||$price<=0){$_SESSION['form_error']='Enter a name, category, and price greater than zero.';redirect('/owner/menu.php'.($id?'?edit='.$id:''));}$q=$pdo->prepare('SELECT id FROM categories WHERE id=:id');$q->execute(['id'=>$cat]);if(!$q->fetch()){$_SESSION['form_error']='Choose an existing category.';redirect('/owner/menu.php'.($id?'?edit='.$id:''));}$q=$pdo->prepare('SELECT id FROM menu_items WHERE name=:name AND id!=:id');$q->execute(['name'=>$name,'id'=>$id]);if($q->fetch()){$_SESSION['form_error']='A menu item with that name already exists.';redirect('/owner/menu.php'.($id?'?edit='.$id:''));}$data=['name'=>$name,'cat'=>$cat,'price'=>$price,'description'=>trim((string)($_POST['description']??''))?:null,'available'=>!empty($_POST['is_available']),'id'=>$id];if($a==='edit'&&$id){$pdo->prepare('UPDATE menu_items SET category_id=:cat,name=:name,description=:description,price=:price,is_available=:available WHERE id=:id')->execute($data);menu_redirect('Menu item saved.');}$pdo->prepare('INSERT INTO menu_items(category_id,name,description,price,is_available) VALUES(:cat,:name,:description,:price,:available)')->execute($data);menu_redirect('Menu item added.'); }
$edit=null;if(isset($_GET['edit'])){$q=$pdo->prepare('SELECT * FROM menu_items WHERE id=:id');$q->execute(['id'=>(int)$_GET['edit']]);$edit=$q->fetch()?:null;}$arch=isset($_GET['archived']);$cats=$pdo->query('SELECT id,name FROM categories WHERE is_archived=0 ORDER BY name')->fetchAll();$selected=(int)($_GET['category']??0);$sql='SELECT m.*,c.name category_name FROM menu_items m JOIN categories c ON c.id=m.category_id WHERE '.($arch?'1=1':'m.is_archived=0').($selected?' AND m.category_id=:category':'').' ORDER BY c.name,m.name';$q=$pdo->prepare($sql);$q->execute($selected?['category'=>$selected]:[]);$items=$q->fetchAll();$page_title='Menu';$theme='owner';require __DIR__.'/../includes/header.php';
?><main class="app-owner-page"><div class="app-page-heading"><div><p class="eyebrow">Owner tools</p><h1>Menu<span>.</span></h1></div><a class="app-toggle-link" href="<?=e(BASE_URL)?>/owner/menu.php<?=$arch?'':'?archived=1'?>"><?=$arch?'Hide archived':'Show archived'?></a></div><?php if(!empty($_SESSION['flash'])):?><p class="app-message app-message-success"><?=e((string)$_SESSION['flash']);unset($_SESSION['flash']);?></p><?php endif;?><section class="app-admin-grid"><form method="post" class="app-form-card"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="<?=$edit?'edit':'add'?>"><?php if($edit):?><input type="hidden" name="id" value="<?=(int)$edit['id']?>"><?php endif;?><h2><?=$edit?'Edit menu item':'Add menu item'?></h2><?php if(!empty($_SESSION['form_error'])):?><p class="app-form-error"><?=e((string)$_SESSION['form_error']);unset($_SESSION['form_error']);?></p><?php endif;?><label class="app-field">Name<input name="name" required value="<?=e($edit['name']??'')?>"></label><label class="app-field">Category<select name="category_id" required><option value="">Choose category</option><?php foreach($cats as $c):?><option value="<?=(int)$c['id']?>" <?=((int)($edit['category_id']??0)===(int)$c['id'])?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select></label><label class="app-field">Description<textarea name="description"><?=e($edit['description']??'')?></textarea></label><label class="app-field">Price<input name="price" type="number" min="0.01" step="0.01" required value="<?=e((string)($edit['price']??''))?>"></label><label class="app-check"><input name="is_available" type="checkbox" value="1" <?=(!$edit||$edit['is_available'])?'checked':''?>> Available</label><button class="primary-button" type="submit">Save menu item</button></form><section class="app-list-card"><div class="app-product-grid"><?php foreach($items as $item):?><article class="product-card app-product-card"><div class="product-body"><span class="app-item-category"><?=e($item['category_name'])?></span><div class="product-title-row"><h3><?=e($item['name'])?></h3><span class="product-price"><?=e(peso($item['price']))?></span></div><p><?=e($item['description']??'')?></p><div class="app-card-actions"><a class="app-table-link" href="?edit=<?=(int)$item['id']?>">Edit</a><form method="post" class="app-inline-form"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$item['id']?>"><input type="hidden" name="action" value="availability"><input type="hidden" name="is_available" value="<?=$item['is_available']?0:1?>"><button class="app-table-link"><?=$item['is_available']?'Unavailable':'Available'?></button></form><form method="post" class="app-inline-form"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$item['id']?>"><input type="hidden" name="action" value="<?=$item['is_archived']?'restore':'archive'?>"><button class="app-table-link"><?=$item['is_archived']?'Restore':'Archive'?></button></form></div></div></article><?php endforeach;?></div></section></section></main><?php require __DIR__.'/../includes/footer.php';?>
